msgs, err := ch.Consume("orders", "worker", false, false, false, false, nil)
if err != nil { log.Fatal(err) }
for {                                  // rests in the receive while idle
    select {
    case d, ok := <-msgs:
        if !ok { return }              // client closed the channel
        if err := handle(d.Body); err != nil { d.Nack(false, true); continue }
        d.Ack(false)
    case <-ctx.Done():
        return                         // drain in-flight work before exit
    }
}
